function setup() {
	createCanvas(650, 650);
	background(255, 250, 240);
	translate(75, 75);
	for (let x = 0; x < 6; x++) {
		for (let y = 0; y < 6; y++) {
			push();
			translate(x * 100 + random(-2, 2), y * 100 + random(-2, 2));
			rotate(random(-0.04, 0.04));
			succulent();
			pop();
		}
	}
}

function succulent() {
	const leaf = generateLeaf();
	const initalAngle = random(TAU);
	const leafCount = 12 + floor(abs(randomGaussian(4, 8)));
	const leafSpacing = random(8, 20) / leafCount;
	const leafRatio = 0.8 + abs(randomGaussian(0, 0.4));
	const planLean = p5.Vector.random2D().mult(randomGaussian(0, 0.3));
	const debrisCount = random([0, 2, floor(abs(randomGaussian(0, 12)))]);

	push();
	// draw pot
	drawingContext.shadowBlur = 6;
	drawingContext.shadowOffsetX = 3;
	drawingContext.shadowOffsetY = 3;
	drawingContext.shadowColor = "black";
	stroke(random(["#9D2235", "#800500", "#540b0c", "#9D2235", "#B75E4A"]));
	fill(random(["#653818", "#4E3524", "#3c1321", "#483c32", "#321a18"]));
	strokeWeight(random(2, 4));
	rect(-46, -46, 92, 92, random([2, 5, 10, 15, 25, 50]));
	drawingContext.shadowColor = "transparent";

	drawingContext.shadowBlur = 5;
	drawingContext.shadowOffsetX = 3;
	drawingContext.shadowOffsetY = 3;
	drawingContext.shadowColor = "rgba(0, 0, 0, 0.5)";

	// draw pebbles / wood chips
	for (let i = 0; i < debrisCount; i++) {
		push();
		const a = random(TAU);
		const d = sq(random(0, sqrt(38)));
		const x = sin(a) * d;
		const y = cos(a) * d;
		translate(x, y);
		noStroke();
		switch (floor(random(0, 4))) {
			case 0:
			case 1:
				fill(random(["#393D47", "#888B8D", "#8c92ac", "#C4B6A6", "#d1cbc1"]));
				ellipse(0, 0, random(4, 6), random(4, 6));
				break;
			case 2:
				fill(random(["#a94007", "#C46316", "#a0522d", "#483c32", "#321a18"]));
				rotate(random(TAU));
				const s = random(14, 16);
				rect(-2, -s / 2, 4, s);
				break;
			case 3:
				fill(random(["#a94007", "#C46316", "#a0522d", "#483c32", "#321a18"]));
				rotate(random(TAU));
				for (let i = 0; i < 4; i++) {
					translate(random(-2, -2), random(-2, 2));
					var s = random(8, 15);
					rect(-1.5, -s / 2, 3, s);
				}
		}
		pop();
	}
	drawingContext.shadowColor = "transparent";

	// draw shadows but different
	fill(0, 25);
	noStroke();
	circle(0, 0, leafCount * leafSpacing * 2);
	circle(0, 0, leafCount * leafSpacing * 3);
	circle(0, 0, leafCount * leafSpacing * 4);

	// draw leaves
	drawingContext.shadowBlur = 5;
	drawingContext.shadowColor = "rgba(0, 0, 0, 0.8)";
	rotate(initalAngle);
	for (let i = leafCount; i >= 0; i--) {
		drawingContext.shadowOffsetX = i * 0.15 + 1;
		drawingContext.shadowOffsetY = i * 0.15 + 1;
		push();
		translate(planLean.x * (leafCount - i), planLean.y * (leafCount - i));
		rotate(i * (1 + sqrt(3)) / 2); // no idea how I got this number
		translate((i + 3) * leafSpacing, 0);
		var s = 10 * sqrt(i + 4) * random(0.9, 1.1);
		image(leaf, -s / 2, -s / 2 * leafRatio, s, s * leafRatio)
		pop();
	}

	drawingContext.shadowColor = "transparent";

	pop();
}

function generateLeaf() {
	const g = createGraphics(100, 100);
	const colors = random([
		["#006E33"],
		["#4E5b31"],
		["#154734"],
		["#009A17"],
		["#009A44"],
		["#009A17"],
		["#004C54"],
		["#9CB571"],
		["#3E471A"],
		["#405943"],
		["#9CB984"],
		["#005761"],
		["#B0B57F"],
		["#006E33"],
		["#4E5b31"],
		["#154734"],
		["#009A17"],
		["#009A44"],
		["#009A17"],
		["#004C54"],
		["#9CB571"],
		["#3E471A"],
		["#405943"],
		["#9CB984"],
		["#005761"],
		["#B0B57F"],
		["#C8D83B"],
		["#FFB673"],
		["#C6CFC3"],
		["#3E471A", "#81873C", "#B8936F", "#8D4453"],
		["#C7A1BB", "#C7A1BB", "#E5E0E8", "#96B8D5"],
		["#44d7a8", "#ADDFB3"],
		["#AA3659", "#AA3659", "#EA82AB"],
		["#ADDFB3", "#ADDFB3", "#ADDFB3", "#ADDFB3", "#A0D2A8", "#A0D2A8", "#651C32"],
		["#F6BE00", "#F0D509", "#FFE900", "#FFE900", "#FFE900", "#FFA400", "#FFA400", "#ED1D24"],
		["#40D0B3", "#40D0B3", "#ADDFB3", "#77dd77"],
		["#807960", "#696148", "#AE9C91", "#4C3942"]
	]);
	g.strokeWeight(abs(randomGaussian(0, 2.5)) + 1);
	if (colors.length === 1) {
		g.stroke(lerpColor(color(colors[0]), color("black"), 0.4));
		g.fill(colors[0]);
	} else {
		const fillGrad = drawingContext.createRadialGradient(30, 50, 0, 20, 50, 62);
		const strokeGrad = drawingContext.createRadialGradient(30, 50, 0, 20, 50, 62);
		for (let i = 0; i < colors.length; i++) {
			fillGrad.addColorStop(i / (colors.length - 1), colors[i]);
			strokeGrad.addColorStop(i / (colors.length - 1), lerpColor(color(colors[i]), color("black"), 0.4).toString());
		}

		g.drawingContext.fillStyle = fillGrad;
		g.drawingContext.strokeStyle = strokeGrad;
	}

	switch (random([0, 0, 0, 0, 0, 1, 1, 2])) {
		case 0:
			g.arc(50, 24, 100, 80, PI * 0.5 - 1, PI * 0.5 + 1, OPEN);
			g.arc(50, 76, 100, 80, PI * 1.5 - 1, PI * 1.5 + 1, OPEN);
			break;
		case 1:
			g.ellipse(50, 50, 90, 25);
			break;
		case 2:
			g.ellipse(50, 50, 90, 75);
			break;
	}
	if (random(1) < 0.15) {
		g.stroke(random(["#C6CFC3", "#F9C78F", "#FFFFFF"]));
		g.strokeWeight(1);
		for (let i = 0; i < 4; i++) {
			g.line(85, 50, random(100, 98), random(45, 55));
		}
	}
	return g;
}

